import math

import torch
from torch import Tensor

PARALLEL_THRESHOLD = 1e-4


def slerp_tensor(a: Tensor, b: Tensor, t: float) -> Tensor:
    if a.shape != b.shape:
        raise ValueError(f"shape mismatch: {tuple(a.shape)} vs {tuple(b.shape)}")
    a32 = a.float().flatten()
    b32 = b.float().flatten()
    dot = float(torch.dot(a32, b32).item())
    if dot < 0.0:
        b32 = -b32
        dot = -dot
    norm_a = float(torch.linalg.vector_norm(a32).item())
    norm_b = float(torch.linalg.vector_norm(b32).item())
    if norm_a == 0.0 or norm_b == 0.0:
        return torch.lerp(a32, b32, t).reshape(a.shape).to(a.dtype)
    cosine = max(-1.0, min(1.0, dot / (norm_a * norm_b)))
    theta = math.acos(cosine)
    if theta < PARALLEL_THRESHOLD:
        return torch.lerp(a32, b32, t).reshape(a.shape).to(a.dtype)
    sin_theta = math.sin(theta)
    weight_a = math.sin((1.0 - t) * theta) / sin_theta
    weight_b = math.sin(t * theta) / sin_theta
    return (weight_a * a32 + weight_b * b32).reshape(a.shape).to(a.dtype)


def slerp_state_dicts(
    state_a: dict[str, Tensor], state_b: dict[str, Tensor], t: float
) -> dict[str, Tensor]:
    if state_a.keys() != state_b.keys():
        raise ValueError("state dicts have different keys, cannot merge")
    merged: dict[str, Tensor] = {}
    for key, tensor_a in state_a.items():
        tensor_b = state_b[key]
        if tensor_a.is_floating_point() and tensor_b.is_floating_point():
            merged[key] = slerp_tensor(tensor_a, tensor_b, t)
        else:
            merged[key] = tensor_a.clone()
    return merged
